/* ============================================================
   Montserrat per jsPDF - Marco De Vecchi / Tech-Check
   ------------------------------------------------------------
   QUATTRO stili: normal, bold, italic, bolditalic.
   Servono tutti: se ne manca uno, jsPDF solleva un'eccezione
   appena il codice chiede quello stile e il PDF non viene
   generato affatto.

   I font sono ridotti ai soli caratteri usati (latino, accenti
   italiani, euro, virgolette tipografiche, frecce): circa 17 KB
   per stile invece di 330 KB.

   USO in index.html, DOPO lo script di jsPDF, entrambi con defer:

     <script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js" defer></script>
     <script src="montserrat-jspdf.js" defer></script>
   ============================================================ */
(function () {
    if (!window.jspdf || !window.jspdf.jsPDF) {
        console.error("montserrat-jspdf.js: jsPDF non caricato. Controlla l'ordine degli script.");
        return;
    }
    var F = {
        normal:     "",
        bold:       "",
        italic:     "",
        bolditalic: ""
    };
    var FILE = {
        normal:     "Montserrat-Regular.ttf",
        bold:       "Montserrat-SemiBold.ttf",
        italic:     "Montserrat-Italic.ttf",
        bolditalic: "Montserrat-SemiBoldItalic.ttf"
    };

    var registra = function () {
        for (var stile in FILE) {
            this.addFileToVFS(FILE[stile], F[stile]);
            this.addFont(FILE[stile], "Montserrat", stile);
        }
    };

    window.jspdf.jsPDF.API.events.push(["addFonts", registra]);
})();
